INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(23901, 'Luke 3:3', 'Luke', 3, 3, '&nbsp;هغه د اُردن په ټوله سيمه کښې ګېرچاپېره وګرځېدو او دا بيان يې کولو چې د توبې بپتسمه واخلئ او ستاسو ګناهونه به معاف شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23902, 'Luke 3:4', 'Luke', 3, 4, '&nbsp;څنګه چې د يشعياه نبى په صحيفه کښې ليکلے شوى دى چې، ”په بيابان کښې د نعرې وهونکى آواز دے چې، د مالِک خُدائ لاره جوړه کړئ او د هغۀ لارې نېغې کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23903, 'Luke 3:5', 'Luke', 3, 5, '&nbsp;هره دره به ډکه شى، هره غونډۍ او غر به هوار شى. کاږۀ به نېغ کړے شى، او ناهمواره لار به هواره کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23904, 'Luke 3:6', 'Luke', 3, 6, '&nbsp;او ټول مخلوق به د خُدائ پاک خلاصون ووينى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23905, 'Luke 3:7', 'Luke', 3, 7, '&nbsp;ګڼ خلق بهر راووتل چې د يحيىٰ نه بپتسمه واخلى خو هغۀ هغوئ ته وفرمائيل چې، ”اے د مارانو بچو، تاسو ته چا خبردارے درکړو چې د راتلونکى غضب نه وتښتئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23906, 'Luke 3:8', 'Luke', 3, 8, '&nbsp;نو داسې کارونه وکړئ چې ورنه ستاسو د توبې ايستلو پته ولګى. تاسو ځان سره داسې سوچ مۀ کوئ چې ګنې تاسو د اِبراهيم اولاد يئ، ځکه چې زۀ درته دا وايم چې خُدائ پاک د دې کاڼو نه هم د اِبراهيم دپاره اولاد پېدا کولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23907, 'Luke 3:9', 'Luke', 3, 9, '&nbsp;اوس هم د ونو جرړو ته تبر نيولے شوے دے او هره هغه ونه چې ښۀ مېوه نۀ نيسى هغه به پرې کړے شى او د اور لمبو ته به اچولے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23908, 'Luke 3:10', 'Luke', 3, 10, '&nbsp;خلقو ترې تپوس وکړو، ”نو بيا مونږ څۀ وکړو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23909, 'Luke 3:11', 'Luke', 3, 11, '&nbsp;هغۀ جواب ورکړو چې، ”د کوم سړى سره چې دوه قميصونه وى، يو دې هغۀ له ورکړى چې د چا سره يو هم نۀ وى، او د چا سره چې خوراک وى هغه دې هم داسې وکړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23910, 'Luke 3:12', 'Luke', 3, 12, '&nbsp;ځينې محصولچيان هم بپتسمې اخستلو له راغلى وُو او هغوئ ترې تپوس وکړو چې، ”اُستاذه. مونږ څۀ وکړو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23911, 'Luke 3:13', 'Luke', 3, 13, '&nbsp;هغۀ ورته وفرمائيل چې، ”ستاسو دپاره چې څۀ مقرر شوى دى د هغې نه زيات مۀ اخلئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23912, 'Luke 3:14', 'Luke', 3, 14, '&nbsp;سپاهيانو هم ترېنه دا تپوس وکړو چې، ”مونږ څۀ وکړو؟“ هغوئ ته يې وفرمائيل چې، ”د چا نه په زوره پېسې مۀ اخلئ او په چا د دروغو اِلزام مۀ لګوئ، په خپله تنخواه صبر کوئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23913, 'Luke 3:15', 'Luke', 3, 15, '&nbsp;خو ټول خلق د مسيح په اِنتظار وُو او د يحيىٰ په حقله يې په خپلو زړُونو کښې سوچ کولو چې ګنې هغه به مسيح وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23914, 'Luke 3:16', 'Luke', 3, 16, '&nbsp;خو يحيىٰ هغوئ ټولو ته وفرمائيل چې، ”زۀ تاسو له په اوبو بپتسمه درکوم خو څوک چې راتلونکے دے هغه زما نه ډېر زورَور دے، او زۀ د هغۀ د پېزار د تسمو د پرانستلو جوګه هم نۀ يم. هغه به تاسو ته په روحُ القُدس او په اور بپتسمه درکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23915, 'Luke 3:17', 'Luke', 3, 17, '&nbsp;ښاخۍ د هغۀ په لاس کښې ده. هغه به خپل درمند په ښۀ شان پاکوى او غنم به په خپله خمبه کښې جمع کوى، خو بوس به په هغه اور کښې سوزوى چې هيڅکله نۀ مرى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23916, 'Luke 3:18', 'Luke', 3, 18, '&nbsp;په دې شان سره هغۀ خلق نور هم ډاډه کول او زېرے يې ورته اورولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23917, 'Luke 3:19', 'Luke', 3, 19, '&nbsp;خو يحيىٰ هيروديس ګورنر د خپل ورور د ښځې هيرودياس سره په وادۀ کولو او په نورو بدو کارونو ملامته کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23918, 'Luke 3:20', 'Luke', 3, 20, '&nbsp;خو د دې ټولو بدو کارونو دپاسه يې يحيىٰ ګرفتار کړو او په قېدخانه کښې يې واچولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23919, 'Luke 3:21', 'Luke', 3, 21, '&nbsp;کله چې ټولو خلقو بپتسمه واخسته نو عيسىٰ هم بپتسمه واخسته، او چې دُعا يې کوله نو آسمان پرانستے شو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23920, 'Luke 3:22', 'Luke', 3, 22, '&nbsp;او روحُ القُدس د يوې کونترې په شکل په عيسىٰ راکوز شو او د آسمان نه يو آواز راغلو چې، ”تۀ زما محبوب زوئ يې، ستا نه زۀ راضى يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23921, 'Luke 3:23', 'Luke', 3, 23, '&nbsp;څۀ وخت چې عيسىٰ خپل خِدمت شروع کړو نو تقريباً د دېرشو کالو وو او د خلقو په خيال دے د يوسف زوئ وو، زوئ د عيلى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23922, 'Luke 3:24', 'Luke', 3, 24, '&nbsp;زوئ د متات، زوئ د ليوى، زوئ د مِلکى، زوئ د ينا، زوئ د يوسف،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23923, 'Luke 3:25', 'Luke', 3, 25, '&nbsp;زوئ د متتياه، زوئ د عاموس، زوئ د نحُوم، زوئ د اِسلياه، زوئ د نجى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23924, 'Luke 3:26', 'Luke', 3, 26, '&nbsp;زوئ د ماعت، زوئ د متتياه، زوئ د شمعى، زوئ د يوسيچ، زوئ د يوداه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23925, 'Luke 3:27', 'Luke', 3, 27, '&nbsp;زوئ د يوحنا، زوئ د ريسا، زوئ د زرُبابل، زوئ د شلتى‌اېل، زوئ د نيرى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23926, 'Luke 3:28', 'Luke', 3, 28, '&nbsp;زوئ د مِلکى، زوئ د ادى، زوئ د قوسام، زوئ د اِلمدام، زوئ د عير،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23927, 'Luke 3:29', 'Luke', 3, 29, '&nbsp;زوئ د يشوَع، زوئ د اِلى‌عزر، زوئ د يوريم، زوئ د متات، زوئ د ليوى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23928, 'Luke 3:30', 'Luke', 3, 30, '&nbsp;زوئ د شمعون، زوئ د يهوداه، زوئ د يوسف، زوئ د يونام، زوئ د اِلياقيم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23929, 'Luke 3:31', 'Luke', 3, 31, '&nbsp;زوئ د ملياه، زوئ د مِناه، زوئ د متتاه، زوئ د ناتن، زوئ د داؤد،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23930, 'Luke 3:32', 'Luke', 3, 32, '&nbsp;زوئ د يَسى، زوئ د عوبيد، زوئ د بوعز، زوئ د سلمون، زوئ د نحشون،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23931, 'Luke 3:33', 'Luke', 3, 33, '&nbsp;زوئ د عمى‌نداب، زوئ د ادمين، زوئ د ارنى، زوئ د حصرون، زوئ د فارص، زوئ د يهوداه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23932, 'Luke 3:34', 'Luke', 3, 34, '&nbsp;زوئ د يعقوب، زوئ د اِسحاق، زوئ د اِبراهيم، زوئ د تارح، زوئ د نحور،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23933, 'Luke 3:35', 'Luke', 3, 35, '&nbsp;زوئ د سروګ، زوئ د رعو، زوئ د فلج، زوئ د عِبر، زوئ د سِلح،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23934, 'Luke 3:36', 'Luke', 3, 36, '&nbsp;زوئ د قينان، زوئ د ارفکسد، زوئ د شيم، زوئ د نوح، زوئ د لمک،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23935, 'Luke 3:37', 'Luke', 3, 37, '&nbsp;زوئ د مِتهوشله، زوئ د حنوک، زوئ د يارد، زوئ د مهلل‌ايل، زوئ د قينان،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23936, 'Luke 3:38', 'Luke', 3, 38, '&nbsp;زوئ د انوش، زوئ د شيث، زوئ د آدم چې د خُدائ پاک د طرف نه وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23937, 'Luke 4:1', 'Luke', 4, 1, '&nbsp;عيسىٰ چې د روحُ القُدس نه معمور وو او د اُردن د سيند نه واپس شو نو روحُ القُدس هغه بيابان ته بوتلو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23938, 'Luke 4:2', 'Luke', 4, 2, '&nbsp;چرته چې هغه تر څلوېښتو ورځو پورې په بيابان کښې د اِبليس په لمسون کښې وآزمائيلے شو. په دې دومره ورځو کښې عيسىٰ هيڅ ونۀ خوړل او په آخر کښې هغه نار نهور شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23939, 'Luke 4:3', 'Luke', 4, 3, '&nbsp;اِبليس هغۀ ته ووئيل چې، ”کۀ تۀ د خُدائ پاک زوئ يې نو دې کاڼى ته حکم وکړه چې روټۍ شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23940, 'Luke 4:4', 'Luke', 4, 4, '&nbsp;عيسىٰ جواب ورکړو، ”صحيفې فرمائى چې، بنى آدم تش په روټۍ نۀ پائى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23941, 'Luke 4:5', 'Luke', 4, 5, '&nbsp;بيا اِبليس هغه په لوړه وخېژولو او د دُنيا ټولې بادشاهۍ يې د سترګو په رپ کښې ورښکاره کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23942, 'Luke 4:6', 'Luke', 4, 6, '&nbsp;او اِبليس ورته ووئيل چې، ”زۀ به د دې ټولو اختيار تا له درکړم او هغه شان او شوکت هم چې د دې سره تړلى وى ځکه چې دا ما ته په اختيار کښې راکړے شوى دى او زۀ يې هغه چا له ورکوم چا له چې يې زما زړۀ غواړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23943, 'Luke 4:7', 'Luke', 4, 7, '&nbsp;کۀ تۀ ما ته صرف سجده وکړې نو دا هر څۀ به زۀ تا له درکړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23944, 'Luke 4:8', 'Luke', 4, 8, '&nbsp;عيسىٰ جواب ورکړو، ”صحيفې فرمائى چې، تۀ تش مالِک خُدائ پاک ته سجده کوه او صرف هم د هغۀ عبادت کوه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23945, 'Luke 4:9', 'Luke', 4, 9, '&nbsp;بيا اِبليس هغه يروشلم ته بوتلو او د خُدائ پاک د کور د مينارې په سر يې ودرولو او ورته يې ووئيل چې، ”کۀ تۀ د خُدائ زوئ يې نو خپل ځان دلته نه ښکته وغورزوه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23946, 'Luke 4:10', 'Luke', 4, 10, '&nbsp;ځکه چې صحيفې وائى چې، هغه به ستا په حقله خپلو فرښتو له حُکم ورکړى چې ستا حفاظت وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23947, 'Luke 4:11', 'Luke', 4, 11, '&nbsp;او هغوئ به تا په خپلو لاسونو کښې پورته کړى هسې نه چې په کاڼى تيندک وخورې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23948, 'Luke 4:12', 'Luke', 4, 12, '&nbsp;عيسىٰ هغۀ ته جواب ورکړو، ”دا وئيلے شوى دى چې، تاسو په خپل مالِک خُدائ پاک آزمېښت مۀ کوئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23949, 'Luke 4:13', 'Luke', 4, 13, '&nbsp;دغه شان چې د اِبليس ټول لمسون سر ته ورسېدو نو هغه يې تر بلې موقعې پورې ځانله پرېښودو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23950, 'Luke 4:14', 'Luke', 4, 14, '&nbsp;بيا عيسىٰ د روحُ القُدس د قُدرت نه معمور ګليل ته واپس راغلو او په ټول مُلک کښې د هغۀ آوازه ګېرچاپېره خوره شوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23951, 'Luke 4:15', 'Luke', 4, 15, '&nbsp;او هغۀ د هغوئ په عبادتخانو کښې تعليم ورکولو او ټولو خلقو د هغۀ لوئى بيانوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23952, 'Luke 4:16', 'Luke', 4, 16, '&nbsp;بيا هغه ناصرت ته راغلو چرته چې هغه لوئ شوے وو او د سبت په ورځ عبادتخانې ته د معمول په مطابق لاړو. هغه د کلام د تلاوت دپاره ودرېدلو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23953, 'Luke 4:17', 'Luke', 4, 17, '&nbsp;او ورته د يشعياه نبى طومار ورکړے شو. هغۀ طومار کولاو کړو او هغه ځائ ته راغلو چې په کښې ليکلى وُو چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23954, 'Luke 4:18', 'Luke', 4, 18, '&nbsp;”د مالِک خُدائ روح په ما نازل دے ځکه چې زۀ هغۀ مسح کړے يم، او دې له يې رالېږلے يم چې غريبانانو له زيرے ورکړم، چې قېديانو ته د آزادۍ اعلان وکړم او ړندو ته د بينائى اِعلان وکړم، او چې مظلومان آزاد کړم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23955, 'Luke 4:19', 'Luke', 4, 19, '&nbsp;او په دې کال به د مالِک خُدائ د احساناتو اعلان وکړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23956, 'Luke 4:20', 'Luke', 4, 20, '&nbsp;هغۀ طومار ونغښتو، خادِم ته يې واپس ورکړو او کښېناستو او په عبادتخانه کښې ټولو خلقو هغۀ ته نېغ کتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23957, 'Luke 4:21', 'Luke', 4, 21, '&nbsp;بيا هغۀ هغوئ ته وفرمائيل، ”نن چې تاسو کوم کلام واورېدلو، نو هغه پوره شو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
