(23991, 'Luke 5:11', 'Luke', 5, 11, '&nbsp;کله چې هغوئ کِشتۍ غاړې ته راوستلې نو هر څۀ يې پرېښودل او په هغۀ پسې روان شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
