(23995, 'Luke 5:15', 'Luke', 5, 15, '&nbsp;خو د هغۀ په حقله دا خبرې نورې هم خورې شوې. ډېر خلق د هغۀ اورېدو له راغونډېدل او د خپلو رنځونو نه روغېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23996, 'Luke 5:16', 'Luke', 5, 16, '&nbsp;او هغه به د دُعا دپاره خوشى بيابان ته تلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23997, 'Luke 5:17', 'Luke', 5, 17, '&nbsp;يوه ورځ عيسىٰ تعليم ورکولو او فريسيان او د شرعې عالمان ورته هم نزدې ناست وُو چې د ګليل، د يهوديه او د يروشلم د هر کلى نه راغلى وُو، او د مالِک خُدائ د شفا ورکولو قوت د هغۀ سره وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23998, 'Luke 5:18', 'Luke', 5, 18, '&nbsp;نو بيا يو څو کسانو يو شل سړے په کټ راوړو. هغوئ کوشش وکړو چې هغه وردننه کړى او د عيسىٰ په مخکښې يې کېږدى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23999, 'Luke 5:19', 'Luke', 5, 19, '&nbsp;خو ګڼه دومره زياته وه چې هيڅ لاره يې ونۀ موندله. نو هغوئ پاس وختل او بره د چت نه يې چَوکې اخوا کړې او سورے وکړو او په بستره کښې يې راښکته کړو او د خلقو په مينځ کښې يې د عيسىٰ په مخکښې کېښودو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
